@Polynomial.isUnit_iff : ∀ {R : Type u_1} [inst : Semiring R] [NoZeroDivisors R] {p : Polynomial R},
  IsUnit p ↔ ∃ r, IsUnit r ∧ Polynomial.C r = p
@Polynomial.prime_X : ∀ {R : Type u_1} [inst : CommRing R] [IsDomain R], Prime Polynomial.X
@dvd_prime_pow : ∀ {M : Type u_1} [inst : CommMonoidWithZero M] [IsCancelMulZero M] {p q : M},
  Prime p → ∀ (n : ℕ), q ∣ p ^ n ↔ ∃ i ≤ n, Associated q (p ^ i)
@LaurentPolynomial.exists_T_pow : ∀ {R : Type u_1} [inst : Semiring R] (f : LaurentPolynomial R),
  ∃ n f', Polynomial.toLaurent f' = f * LaurentPolynomial.T ↑n
